sys_script_include.script:
var CiscoSecureAccessSyncPrivateResources = Class.create();
CiscoSecureAccessSyncPrivateResources.prototype = {
	initialize: function () {
	},

	syncApps: function () {
		gs.info("[CSA Sync Private Apps] Starting syncApps...");

		try {
			// === Step 1: Get Access Token from Table ===
			var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
			if (!token) {
				gs.error("Failed to get token");
				return;
			}

			// === Step 2: Call Cisco Secure Access API ===
			var rest = new sn_ws.RESTMessageV2('Cisco Secure Access Private Resources', 'GET Private Resources');
			rest.setRequestHeader("Authorization", "Bearer " + token);
			rest.setRequestHeader("Accept", "application/json");

			var response = rest.execute();
			var status = response.getStatusCode();

			if (status !== 200) {
				gs.error("REST call failed with status: " + status);
				gs.error("Response body: " + response.getBody());
				return;
			}

			var body = response.getBody();
			gs.info("Raw API Response: " + body);

			var parsed = JSON.parse(body);
			var privateApps = parsed.items || [];

			gs.info("Fetched " + privateApps.length + " private apps.");

			// === Step 3: Sync to CMDB ===
			privateApps.forEach(function (app, index) {
				gs.info("Processing App[" + index + "]: " + JSON.stringify(app));

				var gr = new GlideRecord('u_cmdb_ci_application');
				gr.addQuery('name', app.name);
				gr.query();

				if (gr.next()) {
					var updated = false;

					if ((!gr.short_description || gr.short_description.trim() === '') && app.description) {
						gr.short_description = app.description;
						updated = true;
					}

					if ((!gr.u_resource_id || gr.u_resource_id.trim() === '') && app.resourceId) {
						gr.u_resource_id = app.resourceId;
						updated = true;
					}


					if ((!gr.u_created || gr.u_created.trim() === '') && app.createdAt) {
						gr.u_created = app.createdAt;
						updated = true;
					}

					if (gr.isValidField('u_modified') && (!gr.u_modified || gr.u_modified.trim() === '') && app.modifiedAt) {
						gr.u_modified = app.modifiedAt;
						updated = true;
					}

					if (gr.isValidField('u_access_types') && (!gr.u_access_types || gr.u_access_types.trim() === '') && app.accessTypes && app.accessTypes.length > 0) {
						var accessTypesStr = app.accessTypes.map(function (at) { return at.type; }).join(', ');
						gr.u_access_types = accessTypesStr;
						updated = true;
					}

					if (gr.isValidField('u_manufacturer') && (!gr.u_manufacturer || gr.u_manufacturer.trim() === '') && app.manufacturer) {
						gr.u_manufacturer = app.manufacturer;
						updated = true;
					}

					if (gr.isValidField('u_location') && (!gr.u_location || gr.u_location.trim() === '') && app.location) {
						gr.u_location = app.location;
						updated = true;
					}

					if (gr.isValidField('u_approval_status') && (!gr.u_approval_status || gr.u_approval_status.trim() === '') && app.approvalStatus) {
						gr.u_approval_status = app.approvalStatus;
						updated = true;
					}

					if (gr.isValidField('u_maintenance_schedule') && (!gr.u_maintenance_schedule || gr.u_maintenance_schedule.trim() === '') && app.maintenanceSchedule) {
						gr.u_maintenance_schedule = app.maintenanceSchedule;
						updated = true;
					}

					if (gr.isValidField('u_class') && (!gr.u_class || gr.u_class.trim() === '') && app["class"]) {
						gr.u_class = app["class"];
						updated = true;
					}

					if (updated) {
						gr.update();
						gs.info('Updated CMDB app record for: ' + app.name);
					} else {
						gs.info('No updates required for CMDB app: ' + app.name);
					}

				} else {
					// Optionally insert new record if not found
					gs.info("App not found in CMDB, skipping: " + app.name);
				}
			});

		} catch (ex) {
			gs.error("Exception during CSA sync: " + ex.message);
		}

	},

	type: 'CiscoSecureAccessSyncPrivateResources'
};
